"""
Decomposer — orchestrates classification, dimension selection, and micro-query
generation. Checks local KB first via AtomicResolver.
Optional LLM call for smart query generation when available.
"""

import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional

from .dimension_registry import Dimension, get_dimensions
from .micro_query_generator import MicroQuery, MicroQueryGenerator
from .query_classifier import ClassificationResult, QueryClassifier
from ..reasoning.problem_decomposer import AtomicQuestion
from ..reasoning.atomic_resolver import AtomicResolver


@dataclass
class DecompositionTree:
    original_query: str
    query_type: str
    classification_confidence: float
    dimensions: list[Dimension]
    micro_queries: list[MicroQuery]
    pre_resolved: list[dict] = field(default_factory=list)
    context: dict = field(default_factory=dict)

    @property
    def queries_to_fire(self) -> list[MicroQuery]:
        resolved_texts = {r["query"] for r in self.pre_resolved}
        return [q for q in self.micro_queries if q.text not in resolved_texts]

    @property
    def total_queries(self) -> int:
        return len(self.micro_queries)

    @property
    def cached_count(self) -> int:
        return len(self.pre_resolved)

    def to_dict(self) -> dict:
        return {
            "original_query": self.original_query,
            "query_type": self.query_type,
            "classification_confidence": self.classification_confidence,
            "dimensions": [d.to_dict() for d in self.dimensions],
            "micro_queries": [q.to_dict() for q in self.micro_queries],
            "pre_resolved": self.pre_resolved,
            "context": self.context,
            "total_queries": self.total_queries,
            "cached_count": self.cached_count,
            "queries_to_fire": len(self.queries_to_fire),
        }


class Decomposer:
    def __init__(self, resolver: Optional[AtomicResolver] = None, weight_overrides: Optional[dict[str, float]] = None):
        self.classifier = QueryClassifier()
        self.generator = MicroQueryGenerator()
        self.resolver = resolver
        self.weight_overrides = weight_overrides
        if not self.weight_overrides:
            from .template_evolver import TemplateEvolver
            evolver = TemplateEvolver()
            evolved = evolver.get_evolved_weights()
            if evolved:
                self.weight_overrides = evolved

    def decompose(self, query: Optional[str]) -> DecompositionTree:
        if not query or not query.strip():
            return DecompositionTree(
                original_query=query or "",
                query_type="custom",
                classification_confidence=0.0,
                dimensions=[],
                micro_queries=[],
                context={},
            )

"""
CompletionJudge — decides when the intelligence loop should stop.
Deterministic rules, no LLM.
"""

from dataclasses import dataclass

from .money_flow_graph import MoneyFlowGraph


VERDICT_CONTINUE = "CONTINUE"
VERDICT_COMPLETE = "COMPLETE"
VERDICT_INCOMPLETE = "INCOMPLETE"

MIN_VERIFIED_EDGES = 3
MIN_OVERALL_CONFIDENCE = 0.55
MIN_NODES = 4
MAX_CYCLES = 5


@dataclass
class CompletionVerdict:
    verdict: str  # CONTINUE | COMPLETE | INCOMPLETE
    reason: str
    cycle: int
    confidence: float
    verified_edges: int
    total_edges: int
    node_count: int
    gaps_remaining: int
    untested_hypotheses: int

    def to_dict(self) -> dict:
        return {
            "verdict": self.verdict,
            "reason": self.reason,
            "cycle": self.cycle,
            "confidence": self.confidence,
            "verified_edges": self.verified_edges,
            "total_edges": self.total_edges,
            "node_count": self.node_count,
            "gaps_remaining": self.gaps_remaining,
            "untested_hypotheses": self.untested_hypotheses,
        }


class CompletionJudge:
    def __init__(
        self,
        min_verified_edges: int = MIN_VERIFIED_EDGES,
        min_confidence: float = MIN_OVERALL_CONFIDENCE,
        min_nodes: int = MIN_NODES,
        max_cycles: int = MAX_CYCLES,
    ):
        self.min_verified_edges = min_verified_edges
        self.min_confidence = min_confidence
        self.min_nodes = min_nodes
        self.max_cycles = max_cycles

    def judge(self, graph: MoneyFlowGraph, cycle: int, budget_remaining: int) -> CompletionVerdict:
        verified = graph.verified_edge_count(threshold=0.6)
        confidence = graph.overall_confidence()
        node_count = len(graph.nodes)
        gaps = len(graph.find_gaps())
        untested = len(graph.untested_hypotheses())

        base = dict(
            cycle=cycle,
            confidence=round(confidence, 3),
            verified_edges=verified,
            total_edges=len(graph.edges),
            node_count=node_count,
            gaps_remaining=gaps,
            untested_hypotheses=untested,
        )

        if cycle >= self.max_cycles:
            if verified >= self.min_verified_edges and confidence >= self.min_confidence:
                return CompletionVerdict(verdict=VERDICT_COMPLETE, reason="max_cycles_reached_but_sufficient", **base)
            return CompletionVerdict(verdict=VERDICT_INCOMPLETE, reason="max_cycles_exhausted", **base)

        if budget_remaining <= 0:
            if verified >= self.min_verified_edges:
                return CompletionVerdict(verdict=VERDICT_COMPLETE, reason="budget_exhausted_but_sufficient", **base)
            return CompletionVerdict(verdict=VERDICT_INCOMPLETE, reason="budget_exhausted", **base)

        if verified >= self.min_verified_edges and confidence >= self.min_confidence and node_count >= self.min_nodes:
            if untested == 0 or gaps <= 2:
                return CompletionVerdict(verdict=VERDICT_COMPLETE, reason="quality_threshold_met", **base)

        if untested == 0 and gaps == 0:
            return CompletionVerdict(verdict=VERDICT_COMPLETE, reason="no_more_questions", **base)

        return CompletionVerdict(verdict=VERDICT_CONTINUE, reason="more_hypotheses_to_test", **base)

"""
ThinkRunner — standalone orchestrator for /think command.
Full pipeline: decompose → run queries → assemble facts → synthesize.
"""

import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Optional


@dataclass
class PipelineHealth:
    """Tracks which pipeline layers are active vs failed/degraded."""
    layers: dict = field(default_factory=dict)

    def mark(self, name: str, status: str, detail: str = ""):
        self.layers[name] = {"status": status, "detail": detail}

    def ok(self, name: str, detail: str = ""):
        self.mark(name, "ok", detail)

    def fail(self, name: str, detail: str = ""):
        self.mark(name, "failed", detail)

    def skip(self, name: str, detail: str = ""):
        self.mark(name, "skipped", detail)

    @property
    def active_count(self) -> int:
        return sum(1 for v in self.layers.values() if v["status"] == "ok")

    @property
    def total_count(self) -> int:
        return len(self.layers)

    @property
    def health_score(self) -> float:
        return self.active_count / max(self.total_count, 1)

    def to_dict(self) -> dict:
        return {
            "active": self.active_count,
            "total": self.total_count,
            "health_score": round(self.health_score, 2),
            "layers": self.layers,
        }

