def narrow_query(self, task: SearchTask) -> SearchTask:
    """Rewrite a failed query with narrower scope for retry."""
    original = task.query
    narrowing_suffixes = [
        " pricing revenue cost",
        " company size employees",
        " market share percentage",
        " founded year location",
    ]
    suffix_idx = hash(original) % len(narrowing_suffixes)
    narrowed = original.split('"')
    if len(narrowed) >= 2:
        entity = narrowed[1]
        new_query = f'"{entity}"{narrowing_suffixes[suffix_idx]}'
    else:
        new_query = f"{original}{narrowing_suffixes[suffix_idx]}"

    return SearchTask(
        hypothesis=task.hypothesis,
        query=new_query,
